-- Schema v0. Conventions:
--   * Timestamps are Unix milliseconds (INTEGER), so they read the same under any SQLite driver.
--   * IDs are prefixed random strings (u_…, s_…, sec_…) generated by the hub.
--   * JSON columns are TEXT; the hub owns their shape.
--   * STRICT tables, so a wrong type is an error rather than a silent coercion.

-- +goose Up
CREATE TABLE settings (
    key        TEXT PRIMARY KEY,
    value      TEXT NOT NULL,              -- JSON
    updated_at INTEGER NOT NULL
) STRICT;

CREATE TABLE users (
    id            TEXT PRIMARY KEY,
    username      TEXT NOT NULL UNIQUE COLLATE NOCASE,
    password_hash TEXT,                    -- argon2id PHC string; NULL for passkey- or OIDC-only users
    role          TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'operator', 'viewer', 'household')),
    created_at    INTEGER NOT NULL,
    updated_at    INTEGER NOT NULL,
    disabled_at   INTEGER
) STRICT;

-- Exactly one owner can exist. This also makes first-run setup race-free:
-- a second concurrent setup fails on this index.
CREATE UNIQUE INDEX users_single_owner ON users (role) WHERE role = 'owner';

CREATE TABLE sessions (
    id           TEXT PRIMARY KEY,         -- public handle, safe to list and to reference in audit
    token_hash   BLOB NOT NULL UNIQUE,     -- SHA-256 of the cookie token; the token is never stored
    user_id      TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    method       TEXT NOT NULL,            -- how it was established: password (passkey, oidc later)
    created_at   INTEGER NOT NULL,
    expires_at   INTEGER NOT NULL,
    last_seen_at INTEGER NOT NULL,
    ip           TEXT,
    user_agent   TEXT
) STRICT;
CREATE INDEX sessions_user ON sessions (user_id);
CREATE INDEX sessions_expiry ON sessions (expires_at);

CREATE TABLE integration_instances (
    id          TEXT PRIMARY KEY,
    integration TEXT NOT NULL,             -- e.g. proxmox, sonarr
    name        TEXT NOT NULL,
    config      TEXT NOT NULL DEFAULT '{}', -- JSON; credentials appear only as ${secret:…} references
    enabled     INTEGER NOT NULL DEFAULT 1,
    created_at  INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL,
    UNIQUE (integration, name)
) STRICT;

-- Envelope-encrypted secrets; see internal/vault.
CREATE TABLE vault_secrets (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE,
    alg        TEXT NOT NULL,              -- envelope format version
    kek_id     TEXT NOT NULL,              -- fingerprint of the key-encryption key that wrapped data_key
    data_key   BLOB NOT NULL,              -- nonce || sealed per-secret data key
    ciphertext BLOB NOT NULL,              -- nonce || sealed value
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
) STRICT;

CREATE TABLE boards (
    id         TEXT PRIMARY KEY,
    slug       TEXT NOT NULL UNIQUE,
    title      TEXT NOT NULL,
    position   INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
) STRICT;

-- Layout documents come from the TypeScript layout engine (packages/layout) and are
-- opaque to the hub. Each save appends a revision: history and undo survive restarts.
CREATE TABLE layouts (
    board_id       TEXT NOT NULL REFERENCES boards (id) ON DELETE CASCADE,
    revision       INTEGER NOT NULL,
    format_version INTEGER NOT NULL,       -- the layout package's document format version
    document       TEXT NOT NULL,          -- JSON
    created_at     INTEGER NOT NULL,
    created_by     TEXT REFERENCES users (id) ON DELETE SET NULL,
    PRIMARY KEY (board_id, revision)
) STRICT;

-- Append-only action log. A stub in v0; the action engine fills it in v0.2.
-- Rows may be deleted by retention, never updated.
CREATE TABLE audit (
    id     INTEGER PRIMARY KEY AUTOINCREMENT,
    at     INTEGER NOT NULL,
    actor  TEXT NOT NULL,                  -- JSON: user, via, session, ip
    action TEXT NOT NULL,
    target TEXT,
    params TEXT,                           -- JSON
    tier   TEXT,
    result TEXT NOT NULL,
    detail TEXT                            -- JSON: plan, duration, task
) STRICT;
CREATE INDEX audit_at ON audit (at);

-- +goose StatementBegin
CREATE TRIGGER audit_append_only BEFORE UPDATE ON audit
BEGIN
    SELECT RAISE(ABORT, 'audit is append-only');
END;
-- +goose StatementEnd

-- +goose Down
DROP TRIGGER audit_append_only;
DROP TABLE audit;
DROP TABLE layouts;
DROP TABLE boards;
DROP TABLE vault_secrets;
DROP TABLE integration_instances;
DROP TABLE sessions;
DROP TABLE users;
DROP TABLE settings;
